dashboard.definition:
{
  "title": "WMI Subscription Investigation",
  "description": "SOC-Lab-WMI | Object lifecycle and SYSTEM execution | UTC",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "panel_0": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#20272B",
        "count": 20
      },
      "title": "Filter, consumer and binding events",
      "dataSources": {
        "primary": "ds_panel_0"
      }
    },
    "panel_1": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#20272B",
        "count": 20
      },
      "title": "PowerShell execution from WmiPrvSE.exe",
      "dataSources": {
        "primary": "ds_panel_1"
      }
    }
  },
  "dataSources": {
    "ds_panel_0": {
      "type": "ds.search",
      "name": "Filter, consumer and binding events",
      "options": {
        "query": "index=lab_persistence computer=\"MOHAMEDAHMED\" provider=\"Microsoft-Windows-Sysmon\" event_id IN (19,20,21) \"SOC-Lab-WMI\" | eval UTC=substr(utc,12,12), Operation='data.Operation', EventID=event_id, Object=coalesce('data.Name','data.Filter','data.Consumer'), User='data.User' | table UTC Operation EventID Object User | sort 0 UTC",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_panel_1": {
      "type": "ds.search",
      "name": "PowerShell execution from WmiPrvSE.exe",
      "options": {
        "query": "index=lab_persistence computer=\"MOHAMEDAHMED\" provider=\"Microsoft-Windows-Sysmon\" event_id=1 data.CommandLine=\"*Write-Marker.ps1*\" | rex field=data.CommandLine \"-Case (?<Case>\\w+)\" | eval UTC=substr(utc,12,12), User='data.User', Parent='data.ParentImage', PID='data.ProcessId' | search Case=WMI | table UTC Case User Parent PID | sort 0 UTC",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1440,
          "height": 714,
          "display": "auto-scale",
          "backgroundColor": "#171D21"
        },
        "structure": [
          {
            "item": "panel_0",
            "type": "block",
            "position": {
              "x": 24,
              "y": 24,
              "w": 1392,
              "h": 380
            }
          },
          {
            "item": "panel_1",
            "type": "block",
            "position": {
              "x": 24,
              "y": 428,
              "w": 1392,
              "h": 260
            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Investigation",
          "layoutId": "layout_1"
        }
      ]
    }
  }
}
